const MAX_TASKS = 50;
const MAX_TITLE = 1024;
const MAX_NOTES = 4000;

const body = $json.body && typeof $json.body === 'object' && !Array.isArray($json.body)
  ? $json.body
  : {};

const invalid = (errorMessage) => ({
  json: { valid: false, statusCode: 400, errorCode: 'INVALID_REQUEST', errorMessage },
});

const mode = body.mode === 'grouped' ? 'grouped' : 'flat';
const projectGid = typeof body.projectGid === 'string' ? body.projectGid.trim() : '';
if (!/^\d+$/.test(projectGid)) {
  return invalid('Choose an Asana project before pushing.');
}

const rawTasks = Array.isArray(body.tasks) ? body.tasks : [];
if (rawTasks.length === 0) {
  return invalid('Select at least one task to push.');
}
if (rawTasks.length > MAX_TASKS) {
  return invalid(`Push at most ${MAX_TASKS} tasks at a time.`);
}

const tasks = [];
for (const raw of rawTasks) {
  const source = raw && typeof raw === 'object' ? raw : {};
  const title = typeof source.title === 'string' ? source.title.trim() : '';
  if (title.length === 0) {
    return invalid('Every task needs a title.');
  }

  const notes = typeof source.notes === 'string' ? source.notes.trim() : '';
  const assigneeGid = typeof source.assigneeGid === 'string' ? source.assigneeGid.trim() : '';
  const dueOn = typeof source.dueOn === 'string' ? source.dueOn.trim() : '';

  if (assigneeGid && !/^\d+$/.test(assigneeGid)) {
    return invalid('An assignee was not recognised. Pick one from the list.');
  }
  if (dueOn && !/^\d{4}-\d{2}-\d{2}$/.test(dueOn)) {
    return invalid('Due dates must look like 2026-07-30.');
  }

  tasks.push({
    title: title.slice(0, MAX_TITLE),
    notes: notes.slice(0, MAX_NOTES),
    assigneeGid,
    dueOn,
  });
}

const meetingTitle = typeof body.meetingTitle === 'string' && body.meetingTitle.trim()
  ? body.meetingTitle.trim().slice(0, MAX_TITLE)
  : 'Meeting actions';

return {
  json: { valid: true, mode, projectGid, meetingTitle, tasks, grouped: mode === 'grouped' },
};

const info = $('Validate Create Request').first().json;

// The parent node only runs in grouped mode; referencing it otherwise throws.
let parentGid = '';
try {
  const parent = $('Create Parent Task').first().json;
  parentGid = String(parent?.data?.gid ?? '');
} catch (error) {
  parentGid = '';
}

return info.tasks.map((task) => {
  const data = { name: task.title };
  if (task.notes) {
    data.notes = task.notes;
  }
  if (task.dueOn) {
    data.due_on = task.dueOn;
  }
  if (task.assigneeGid) {
    data.assignee = task.assigneeGid;
  }
  if (parentGid) {
    // Subtasks inherit their parent's project.
    data.parent = parentGid;
  } else {
    data.projects = [info.projectGid];
  }
  return { json: { body: { data } } };
});

const info = $('Validate Create Request').first().json;

let parent = null;
try {
  const raw = $('Create Parent Task').first().json;
  if (raw?.data?.gid) {
    parent = {
      gid: String(raw.data.gid),
      name: String(raw.data.name ?? ''),
      url: String(raw.data.permalink_url ?? ''),
    };
  }
} catch (error) {
  parent = null;
}

const created = $input
  .all()
  .map((item) => {
    const data = item.json?.data ?? {};
    return {
      gid: String(data.gid ?? ''),
      name: String(data.name ?? ''),
      url: String(data.permalink_url ?? ''),
    };
  })
  .filter((task) => task.gid);

return {
  json: { created, parent, mode: info.mode, count: created.length },
};
